     */
    func blocksOf(text: String)  -> [Block]
    
    func create(title: String?, body: String) throws  -> NoteMeta
    
    /**
     * Image sources referenced by a note, for the native image loader.
     */
    func imageSources(id: String) throws  -> [String]
    
    func inline(text: String)  -> [Inline]
    
    func list() throws  -> [NoteMeta]
    
    func read(id: String) throws  -> String
    
    /**
     * Force a reindex (after a git pull, or when files changed outside the app).
     */
    func reindex() throws 
    
    func rename(id: String, title: String) throws  -> NoteMeta
    
    /**
     * Absolute path of a vault-relative resource (images etc.).
     */
    func resolveAsset(id: String, src: String) throws  -> String
    
    func root()  -> String
    
    func search(query: String, tags: [String], limit: UInt32)  -> [Hit]
    
    func tags()  -> [TagCount]
    
    func trash(id: String) throws  -> String
    
    /**
     * Overwrite a note. Rejected when the file changed on disk since `seen_mtime_ms`.
     */
    func write(id: String, body: String, seenMtimeMs: Int64) throws  -> NoteMeta
    
}
